export interface Verse {
  id: number;
  sadr: string;
  ajuz?: string;
  text: string;
}

type RawVerse = Omit<Verse, "text"> & { text?: string };
type RawPoem = Omit<Poem, "verses"> & { verses: RawVerse[] };

export interface Poem {
  id: number;
  title: string;
  category: string;
  meter?: string;
  intro?: string;
  verses: Verse[];
}

